import type { Href } from 'expo-router';

/**
 * Typed routes are generated by Metro, so freshly added dynamic routes are not in the generated
 * union until the dev server has run. Paths here are built from validated ids only.
 */
export const href = (path: string): Href => path as Href;

export const routes = {
  pantryItem: (id: string) => href(`/pantry/${id}`),
  pantryEditor: (id: string, query = '') => href(`/pantry-editor/${id}${query}`),
  recipe: (id: string, loaves?: number) =>
    href(`/recipes/${id}${loaves ? `?loaves=${loaves}` : ''}`),
  recipeCost: (id: string, loaves?: number) =>
    href(`/recipes/${id}/cost${loaves ? `?loaves=${loaves}` : ''}`),
  recipeEditor: (id: string, query = '') => href(`/recipe-editor/${id}${query}`),
  ingredientEditor: (query = '') => href(`/recipe-editor/ingredient${query}`),
  stepEditor: (query = '') => href(`/recipe-editor/step${query}`),
  recipes: href('/recipes'),
  bakes: href('/bakes'),
  bake: (id: string) => href(`/bake/${id}`),
  schedulePick: href('/bake/schedule'),
  schedulePlan: (query = '') => href(`/bake/schedule/plan${query}`),
  pantry: href('/pantry'),
  settingsCost: href('/settings/cost'),
} as const;
